query:
# ADMINISTRADOR - lista inicial
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "1") {
    permission { code }
  }
}

# CONTADOR - lista inicial
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "2") {
    permission { code }
  }
}

# CAPTURISTA - lista inicial
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "3") {
    permission { code }
  }
}

# CONSULTA - lista inicial
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "4") {
    permission { code }
  }
}

# María / CAPTURISTA: crear cuenta antes del cambio
mutation {
  createAccount(
    actorCompanyUserId: "3"
    input: {companyId: "1", accountType: CASH,
      name: "María antes 7977002"}
  ) { id name companyId }
}

# José / CAPTURISTA: crear cuenta antes del cambio
mutation {
  createAccount(
    actorCompanyUserId: "4"
    input: {companyId: "1", accountType: CASH,
      name: "José antes 7977002"}
  ) { id name companyId }
}

# Ana / ADMINISTRADOR: agrega accounts.write al capturista
mutation {
  assignPermissionToRole(
    actorCompanyUserId: "1"
    input: {roleId: "3", permissionId: "4"}
  ) { id role { code } permission { code } isActive }
}

# Ana: no se duplica una pareja activa
mutation {
  assignPermissionToRole(
    actorCompanyUserId: "1"
    input: {roleId: "3", permissionId: "4"}
  ) { id role { code } permission { code } isActive }
}

# María / CAPTURISTA: cuenta después del cambio
mutation {
  createAccount(
    actorCompanyUserId: "3"
    input: {companyId: "1", accountType: CASH,
      name: "María después 7977002"}
  ) { id name companyId }
}

# José / CAPTURISTA: cuenta después del cambio
mutation {
  createAccount(
    actorCompanyUserId: "4"
    input: {companyId: "1", accountType: CASH,
      name: "José después 7977002"}
  ) { id name companyId }
}

# Ana: retira accounts.write del capturista
mutation {
  removePermissionFromRole(
    actorCompanyUserId: "1"
    roleId: "3"
    permissionId: "4"
  )
}

# María: rechazo después de retirar el permiso
mutation {
  createAccount(
    actorCompanyUserId: "3"
    input: {companyId: "1", accountType: CASH,
      name: "María retirado 7977002"}
  ) { id name companyId }
}

# José: rechazo después de retirar el permiso
mutation {
  createAccount(
    actorCompanyUserId: "4"
    input: {companyId: "1", accountType: CASH,
      name: "José retirado 7977002"}
  ) { id name companyId }
}

# Pedro / CONSULTA: movimiento rechazado
mutation {
  createTransaction(
    actorCompanyUserId: "5"
    input: {accountId: "1", conceptId: "1",
      transactionType: INCOME, amount: "125.50",
      shortDescription: "Pedro consulta 7977002"}
  ) { id amount shortDescription capturedBy }
}

# Ana: cambia a Pedro de CONSULTA a CAPTURISTA
mutation {
 assignRole(actorCompanyUserId: "1",
   input: {companyUserId: "5", roleId: "3"}) {
   companyUser { user { name } } role { code } isActive
 }
}

# Pedro / CAPTURISTA: movimiento aceptado
mutation {
  createTransaction(
    actorCompanyUserId: "5"
    input: {accountId: "1", conceptId: "1",
      transactionType: INCOME, amount: "125.50",
      shortDescription: "Pedro capturista 7977002"}
  ) { id amount shortDescription capturedBy }
}

# CONTADOR: lista después del cambio de Pedro
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "2") {
    permission { code }
  }
}

# Luis / CONTADOR: todavía puede crear cuentas
mutation {
  createAccount(
    actorCompanyUserId: "2"
    input: {companyId: "1", accountType: CASH,
      name: "Luis contador 7977002"}
  ) { id name companyId }
}

# CONSULTA: lista después del cambio de Pedro
query {
  rolePermissions(actorCompanyUserId: "1", roleId: "4") {
    permission { code }
  }
}

# José / CAPTURISTA: intenta modificar CONSULTA
mutation {
  assignPermissionToRole(
    actorCompanyUserId: "4"
    input: {roleId: "4", permissionId: "6"}
  ) { id role { code } permission { code } isActive }
}

# Ana / ADMINISTRADOR: agrega concepts.write a CONSULTA
mutation {
  assignPermissionToRole(
    actorCompanyUserId: "1"
    input: {roleId: "4", permissionId: "6"}
  ) { id role { code } permission { code } isActive }
}

# Ana: retira concepts.write de CONSULTA
mutation {
  removePermissionFromRole(
    actorCompanyUserId: "1"
    roleId: "4"
    permissionId: "6"
  )
}
